-- Identity is server-owned and remains protected when removed from the catalogue.
CREATE UNIQUE INDEX IF NOT EXISTS occasions_id_organization_uidx ON public.occasions(id,organization);
CREATE TABLE IF NOT EXISTS public.demo_occasions (
 occasion bigint PRIMARY KEY,
 organization bigint NOT NULL REFERENCES public.organizations(id),
 demo_key text NOT NULL CHECK(demo_key IN ('ball','concert','weekend')),
 fixture_version text NOT NULL,
 bank_account bigint NOT NULL UNIQUE REFERENCES eshop.bank_accounts(id),
 is_listed boolean NOT NULL DEFAULT false,
 sort_order integer NOT NULL,
 description text NOT NULL,
 reference_at timestamptz NOT NULL,
 UNIQUE(organization,demo_key,fixture_version),
 FOREIGN KEY(occasion,organization) REFERENCES public.occasions(id,organization)
);
CREATE UNIQUE INDEX IF NOT EXISTS demo_occasions_listed_uidx
 ON public.demo_occasions(organization,demo_key) WHERE is_listed;
ALTER TABLE public.demo_occasions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.demo_occasions FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/demo_occasions/access.sql
CREATE OR REPLACE FUNCTION public.is_demo_occasion(p_occasion bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT EXISTS(SELECT 1 FROM public.demo_occasions WHERE occasion=p_occasion);
$$;
CREATE OR REPLACE FUNCTION public.is_demo_bank_account(p_bank_account bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT EXISTS(SELECT 1 FROM public.demo_occasions WHERE bank_account=p_bank_account);
$$;
CREATE OR REPLACE FUNCTION public.can_read_demo_occasion(p_occasion bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(
  SELECT 1 FROM public.demo_occasions d JOIN public.user_info u
   ON u.organization=d.organization AND u.id=auth.uid()
  WHERE d.occasion=p_occasion AND d.is_listed);
$$;
CREATE OR REPLACE FUNCTION public.check_occasion_writable(p_occasion bigint)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF public.is_demo_occasion(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='DEMO_OCCASION_READ_ONLY';
 END IF;
END $$;
CREATE OR REPLACE FUNCTION public.check_bank_account_writable(p_bank_account bigint)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF public.is_demo_bank_account(p_bank_account) THEN
  RAISE insufficient_privilege USING MESSAGE='DEMO_BANK_ACCOUNT_READ_ONLY';
 END IF;
END $$;
-- This policy is shared by destination discovery and the receipted copy command.
CREATE OR REPLACE FUNCTION public.can_copy_occasion_source(p_occasion bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT auth.uid() IS NOT NULL AND CASE WHEN public.is_demo_occasion(p_occasion)
  THEN public.can_read_demo_occasion(p_occasion)
  ELSE EXISTS(SELECT 1 FROM public.occasions o WHERE o.id=p_occasion
    AND public.get_is_manager_on_unit(o.unit)) END;
$$;
CREATE OR REPLACE FUNCTION public.is_demo_unit(p_unit bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT EXISTS(SELECT 1 FROM public.demo_occasions d JOIN public.occasions o
  ON o.id=d.occasion WHERE o.unit=p_unit);
$$;
REVOKE ALL ON FUNCTION public.can_copy_occasion_source(bigint) FROM PUBLIC,anon;


CREATE OR REPLACE FUNCTION public.demo_unit_can_read(p_unit bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT NOT public.is_demo_unit(p_unit) OR EXISTS(SELECT 1 FROM public.demo_occasions d
  JOIN public.occasions o ON o.id=d.occasion WHERE o.unit=p_unit AND public.can_read_demo_occasion(d.occasion));
$$;


-- Source: database/functions/demo_occasions/row_scope.sql
-- A small closed set of existing relationships, also used by restrictive RLS.
-- No caller can choose a relation or inject SQL.
CREATE OR REPLACE FUNCTION public.demo_entity_is_protected(p_kind text,p_id bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT CASE p_kind
 WHEN 'occasion' THEN public.is_demo_occasion(p_id)
 WHEN 'bank' THEN public.is_demo_bank_account(p_id)
 WHEN 'order' THEN EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'ticket' THEN EXISTS(SELECT 1 FROM eshop.tickets WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'form' THEN EXISTS(SELECT 1 FROM public.forms WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'event' THEN EXISTS(SELECT 1 FROM public.events WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'pool' THEN EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'context' THEN EXISTS(SELECT 1 FROM public.inventory_contexts c JOIN public.inventory_pools p ON p.id=c.inventory_pool
   WHERE c.id=p_id AND public.is_demo_occasion(p.occasion))
 WHEN 'resource' THEN EXISTS(SELECT 1 FROM public.resources WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'product' THEN EXISTS(SELECT 1 FROM eshop.products WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'payment' THEN EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=p_id AND public.is_demo_bank_account(bank_account))
 ELSE false END;
$$;


-- Source: database/functions/demo_occasions/read_policy.sql
GRANT SELECT (occasion,bank_account) ON public.demo_occasions TO anon,authenticated;
DROP POLICY IF EXISTS demo_registry_read ON public.demo_occasions;
CREATE POLICY demo_registry_read ON public.demo_occasions FOR SELECT TO authenticated
 USING(public.can_read_demo_occasion(occasion));


